"""Path of Building 数据文件（Lua）解析器。

PoB 的 `src/Data/` 是从 GGG 客户端 `.dat` 文件导出的 Lua 源码，绝大多数是
**纯字面量表**（文件头写着 "This file is automatically generated, do not edit!"），
因此不需要 Lua 运行时——一个字面量解析器就够。

为什么不跑真的 Lua：
  - 本机没有 Lua/LuaJIT，`runtime/` 里是 Windows DLL；装解释器等于给项目加一个
    平台相关的外部依赖，与「零外部服务、迁到 Windows 不改代码」的约定冲突。
  - 我们**不重算 PoB 的伤害引擎**（项目硬规则 6），所以 `statMap` 里那些
    `mod(...)` / `bit.bor(...)` 调用对知识库毫无用处，没有求值的必要。

因此对函数调用与标识符引用（`mod(...)`、`SkillType.Spell`）不求值，
原样保留成 `LuaOpaque`，让调用方自行决定忽略还是记录原文。
**不静默丢弃**——静默丢弃会让「某个字段没解析出来」和「游戏里确实没这个字段」
无法区分，而那正是会让事实断言出错的地方。

Lua 表的位置项（`{ "文本", type = "Prefix" }` 里的 `"文本"`）按 Lua 语义
存成整数键 1..n，不能丢：`ModExplicit.lua` 的词缀正文就是位置项。
"""

from __future__ import annotations

import re
from dataclasses import dataclass
from pathlib import Path
from typing import Any, Iterator

__all__ = [
    "LuaOpaque",
    "LuaSyntaxError",
    "parse_lua_value",
    "parse_return_table",
    "parse_assignments",
    "load_lua_file",
]


class LuaSyntaxError(ValueError):
    """解析失败。带上出错位置的上下文，便于定位 PoB 格式变化。"""


@dataclass(frozen=True)
class LuaOpaque:
    """未求值的表达式（函数调用、标识符引用、算术式）。保留原文。"""

    src: str

    def __repr__(self) -> str:  # pragma: no cover - 仅调试用
        s = self.src if len(self.src) <= 60 else self.src[:57] + "..."
        return f"LuaOpaque({s!r})"


# ── 词法 ───────────────────────────────────────────────────

#: 主扫描表。顺序有意义：长串与注释必须先于单字符符号匹配。
_TOKEN_RE = re.compile(
    r"""
    (?P<ws>\s+)
  | (?P<longcomment>--\[(?P<lcc_eq>=*)\[)
  | (?P<comment>--[^\n]*)
  | (?P<longstring>\[(?P<ls_eq>=*)\[)
  | (?P<number>
        0[xX][0-9a-fA-F]+
      | (?:\d+\.?\d*|\.\d+)(?:[eE][+-]?\d+)?
    )
  | (?P<string>"(?:[^"\\\n]|\\.)*"|'(?:[^'\\\n]|\\.)*')
  | (?P<name>[A-Za-z_][A-Za-z0-9_]*)
  | (?P<punct>\.\.\.|\.\.|==|~=|<=|>=|[{}\[\]=,;()\.:+\-*/%^#<>])
    """,
    re.VERBOSE,
)

_KEYWORD_VALUES = {"true": True, "false": False, "nil": None}
_ESCAPES = {
    "a": "\a", "b": "\b", "f": "\f", "n": "\n", "r": "\r",
    "t": "\t", "v": "\v", "\\": "\\", '"': '"', "'": "'", "\n": "\n",
}


@dataclass
class _Token:
    kind: str
    value: Any
    pos: int


def _tokenize(text: str) -> list[_Token]:
    out: list[_Token] = []
    i, n = 0, len(text)
    while i < n:
        m = _TOKEN_RE.match(text, i)
        if m is None:
            raise LuaSyntaxError(f"位置 {i} 无法识别：{_context(text, i)}")
        kind = m.lastgroup
        # lastgroup 可能落在内层命名组上，按显式检查取外层类型
        if m.group("ws") is not None:
            i = m.end()
            continue
        if m.group("comment") is not None:
            i = m.end()
            continue
        if m.group("longcomment") is not None:
            i = _skip_long_bracket(text, m.end(), m.group("lcc_eq"), "长注释")[1]
            continue
        if m.group("longstring") is not None:
            value, i = _skip_long_bracket(text, m.end(), m.group("ls_eq"), "长字符串")
            out.append(_Token("string", value, m.start()))
            continue
        if m.group("number") is not None:
            raw = m.group("number")
            out.append(_Token("number", _to_number(raw), m.start()))
            i = m.end()
            continue
        if m.group("string") is not None:
            out.append(_Token("string", _unescape(m.group("string")[1:-1]), m.start()))
            i = m.end()
            continue
        if m.group("name") is not None:
            out.append(_Token("name", m.group("name"), m.start()))
            i = m.end()
            continue
        out.append(_Token("punct", m.group("punct"), m.start()))
        i = m.end()
    return out


def _skip_long_bracket(text: str, start: int, eq: str, what: str) -> tuple[str, int]:
    """处理 `[[...]]` / `[==[...]==]`。返回 (内容, 结束后位置)。"""
    closer = "]" + eq + "]"
    end = text.find(closer, start)
    if end < 0:
        raise LuaSyntaxError(f"{what}未闭合（起始位置 {start}）：{_context(text, start)}")
    body = text[start:end]
    # Lua 规定长括号紧跟的第一个换行被忽略
    if body.startswith("\r\n"):
        body = body[2:]
    elif body.startswith("\n"):
        body = body[1:]
    return body, end + len(closer)


def _to_number(raw: str) -> int | float:
    if raw[:2].lower() == "0x":
        return int(raw, 16)
    if any(ch in raw for ch in ".eE"):
        return float(raw)
    return int(raw)


def _unescape(s: str) -> str:
    if "\\" not in s:
        return s
    out: list[str] = []
    i = 0
    while i < len(s):
        ch = s[i]
        if ch != "\\":
            out.append(ch)
            i += 1
            continue
        i += 1
        if i >= len(s):
            out.append("\\")
            break
        nxt = s[i]
        if nxt in _ESCAPES:
            out.append(_ESCAPES[nxt])
            i += 1
        elif nxt.isdigit():  # \ddd
            j = i
            while j < len(s) and j - i < 3 and s[j].isdigit():
                j += 1
            out.append(chr(int(s[i:j])))
            i = j
        else:
            out.append(nxt)
            i += 1
    return "".join(out)


def _context(text: str, pos: int, width: int = 60) -> str:
    lo = max(0, pos - width // 2)
    return repr(text[lo:pos + width // 2])


# ── 语法 ───────────────────────────────────────────────────

class _Parser:
    def __init__(self, tokens: list[_Token], text: str) -> None:
        self.toks = tokens
        self.text = text
        self.i = 0

    # -- 基础操作 --
    def peek(self, offset: int = 0) -> _Token | None:
        j = self.i + offset
        return self.toks[j] if j < len(self.toks) else None

    def at_punct(self, *vals: str) -> bool:
        t = self.peek()
        return t is not None and t.kind == "punct" and t.value in vals

    def at_name(self, *vals: str) -> bool:
        t = self.peek()
        return t is not None and t.kind == "name" and t.value in vals

    def take(self) -> _Token:
        t = self.peek()
        if t is None:
            raise LuaSyntaxError("输入意外结束")
        self.i += 1
        return t

    def expect_punct(self, val: str) -> _Token:
        t = self.peek()
        if t is None or t.kind != "punct" or t.value != val:
            got = "EOF" if t is None else repr(t.value)
            pos = len(self.text) if t is None else t.pos
            raise LuaSyntaxError(f"期望 {val!r}，实得 {got}：{_context(self.text, pos)}")
        return self.take()

    # -- 值 --
    def parse_value(self) -> Any:
        t = self.peek()
        if t is None:
            raise LuaSyntaxError("期望值，但输入已结束")
        if t.kind in ("string", "number"):
            self.take()
            return t.value
        if t.kind == "name":
            if t.value in _KEYWORD_VALUES:
                self.take()
                return _KEYWORD_VALUES[t.value]
            return self.parse_opaque()
        if t.kind == "punct":
            if t.value == "{":
                return self.parse_table()
            if t.value == "-":  # 负数
                self.take()
                nxt = self.peek()
                if nxt is not None and nxt.kind == "number":
                    self.take()
                    return -nxt.value
                return self.parse_opaque(prefix="-")
            return self.parse_opaque()
        raise LuaSyntaxError(f"无法解析的值：{t!r}")

    def parse_opaque(self, prefix: str = "") -> LuaOpaque:
        """吞掉一个不求值的表达式，保留原文。

        以「遇到当前层的 `,` `;` `}` 就停」为界，同时跟踪括号深度，
        这样 `mod("A", "B", { x = 1 })` 这种带逗号和嵌套表的调用不会被切断。
        """
        start = self.peek().pos  # type: ignore[union-attr]
        depth = 0
        end = start
        while True:
            t = self.peek()
            if t is None:
                break
            if t.kind == "punct":
                if t.value in "([{":
                    depth += 1
                elif t.value in ")]}":
                    if depth == 0:
                        break
                    depth -= 1
                elif t.value in (",", ";") and depth == 0:
                    break
            self.take()
            end = t.pos + len(str(t.value)) if t.kind != "string" else t.pos
        src = self.text[start:self.toks[self.i].pos if self.i < len(self.toks) else len(self.text)]
        return LuaOpaque((prefix + src).strip().rstrip(",;").strip())

    def parse_table(self) -> dict[Any, Any]:
        """表 → dict。位置项按 Lua 语义存成整数键 1..n。"""
        self.expect_punct("{")
        out: dict[Any, Any] = {}
        auto = 0
        while True:
            if self.at_punct("}"):
                self.take()
                return out
            if self.at_punct(",", ";"):
                self.take()
                continue

            key: Any = None
            has_key = False
            if self.at_punct("["):
                self.take()
                key = self.parse_value()
                self.expect_punct("]")
                self.expect_punct("=")
                has_key = True
            else:
                t, t2 = self.peek(), self.peek(1)
                if (
                    t is not None and t.kind == "name"
                    and t2 is not None and t2.kind == "punct" and t2.value == "="
                ):
                    key = t.value
                    self.take()
                    self.take()
                    has_key = True

            value = self.parse_value()
            if has_key:
                out[key] = value
            else:
                auto += 1
                out[auto] = value


# ── 对外入口 ───────────────────────────────────────────────

def parse_lua_value(text: str) -> Any:
    """解析单个 Lua 值（一般是表字面量）。"""
    p = _Parser(_tokenize(text), text)
    return p.parse_value()


def parse_return_table(text: str) -> dict[Any, Any]:
    """解析「整个文件就是一张表」的形式。

    两种写法都支持，因为 PoB 里两种都存在：
      - `return { ... }`                    —— ModExplicit / Gems / 新版 tree.lua
      - `local 名字 = { ... }`（无 return）  —— 旧版 tree.lua（如 2_6）

    找 `return` 时必须确认后面紧跟 `{`：`Skills/*.lua` 那类文件里
    函数体内部也有 `return`，撞上就会解析出一堆无意义的东西。
    """
    toks = _tokenize(text)

    def table_at(idx: int) -> dict[Any, Any] | None:
        if idx >= len(toks) or toks[idx].kind != "punct" or toks[idx].value != "{":
            return None
        p = _Parser(toks, text)
        p.i = idx
        value = p.parse_value()
        return value if isinstance(value, dict) else None

    for idx, t in enumerate(toks):
        if t.kind == "name" and t.value == "return":
            got = table_at(idx + 1)
            if got is not None:
                return got
        # local 名字 = {
        if (
            t.kind == "name" and t.value == "local"
            and idx + 3 < len(toks)
            and toks[idx + 1].kind == "name"
            and toks[idx + 2].kind == "punct" and toks[idx + 2].value == "="
        ):
            got = table_at(idx + 3)
            if got is not None:
                return got

    raise LuaSyntaxError("文件里既没有 `return {表}` 也没有 `local 名字 = {表}`")


def parse_assignments(text: str) -> dict[str, Any]:
    """解析 `名字["键"] = { ... }` / `名字.字段 = { ... }` 形式的文件。

    用于 `Bases/*.lua`（`itemBases["Paua Amulet"] = {...}`）、
    `Bosses.lua`、`Minions.lua`、`Misc.lua`（`data.monsterLifeTable = {...}`）。

    返回 `{键: 值}`。同名重复赋值以**最后一次**为准（Lua 语义）。
    """
    toks = _tokenize(text)
    out: dict[str, Any] = {}
    i = 0
    n = len(toks)
    while i < n:
        t = toks[i]
        if t.kind != "name" or t.value in ("local", "return", "function", "end"):
            i += 1
            continue
        # 名字 后面必须紧跟 ["键"] 或 .字段，再跟 =
        j = i + 1
        key: str | None = None
        if j + 2 < n and toks[j].kind == "punct" and toks[j].value == "[":
            if toks[j + 1].kind in ("string", "number") and \
               toks[j + 2].kind == "punct" and toks[j + 2].value == "]":
                key = str(toks[j + 1].value)
                j += 3
        elif j + 1 < n and toks[j].kind == "punct" and toks[j].value == "." \
                and toks[j + 1].kind == "name":
            key = toks[j + 1].value
            j += 2
        if key is None or not (j < n and toks[j].kind == "punct" and toks[j].value == "="):
            i += 1
            continue
        p = _Parser(toks, text)
        p.i = j + 1
        out[key] = p.parse_value()
        i = p.i
    return out


def load_lua_file(path: Path) -> str:
    """统一读取。显式 UTF-8——Windows 默认 cp936 会破坏内容。"""
    return path.read_text(encoding="utf-8", errors="replace")


def iter_long_strings(text: str) -> Iterator[str]:
    """依次产出文件里的 `[[...]]` 长字符串。

    `Uniques/*.lua` 是 `return { [[条目1]], [[条目2]] }`，每个长字符串就是
    一件装备的文本块。走这条捷径而不是完整解析，是因为唯一装备的价值全在
    文本块本身，且这样对格式变化更皮实。
    """
    i = 0
    n = len(text)
    while i < n:
        m = re.compile(r"\[(=*)\[").search(text, i)
        if m is None:
            return
        # 跳过注释里的 `--[[`
        line_start = text.rfind("\n", 0, m.start()) + 1
        if "--" in text[line_start:m.start()]:
            i = m.end()
            continue
        body, i = _skip_long_bracket(text, m.end(), m.group(1), "长字符串")
        yield body
